    static String get(String file, int size, int stroke10) {
        String j = M.get(file);
        if (j == null) return null;
        String s = String.format(Locale.US, "%.1f", stroke10 / 10f);
        String s2 = String.format(Locale.US, "%.1f", stroke10 * 0.085f);
        return j.replace("@@D@@", String.valueOf(size))
                .replace("@@S2@@", s2)
                .replace("@@S@@", s);
    }
    /** Monta um Lottie com uma imagem PNG embutida, centralizada e com o diametro pedido. */
    static String imageLottie(byte[] png, int size) {
        BitmapFactory.Options o = new BitmapFactory.Options();
        o.inJustDecodeBounds = true;
        BitmapFactory.decodeByteArray(png, 0, png.length, o);
        int w = Math.max(1, o.outWidth), h = Math.max(1, o.outHeight);
        float sc = size * 4f / Math.max(w, h) * 100f;
        String b64 = Base64.encodeToString(png, Base64.NO_WRAP);
        return "{\"v\":\"5.9.1\",\"fr\":60,\"ip\":0,\"op\":90,\"w\":288,\"h\":288,\"nm\":\"custom\",\"ddd\":0,"
                + "\"assets\":[{\"id\":\"img\",\"w\":" + w + ",\"h\":" + h + ",\"u\":\"\",\"p\":\"data:image/png;base64," + b64 + "\",\"e\":1}],"
                + "\"layers\":[{\"ddd\":0,\"ind\":1,\"ty\":2,\"nm\":\"icon\",\"refId\":\"img\",\"sr\":1,"
                + "\"ks\":{\"o\":{\"a\":0,\"k\":100},\"r\":{\"a\":0,\"k\":0},\"p\":{\"a\":0,\"k\":[144,144,0]},"
                + "\"a\":{\"a\":0,\"k\":[" + (w / 2f) + "," + (h / 2f) + ",0]},"
                + "\"s\":{\"a\":0,\"k\":[" + sc + "," + sc + ",100]}},"
                + "\"ao\":0,\"ip\":0,\"op\":90,\"st\":0,\"bm\":0}],\"markers\":[]}";
    }
